<script setup lang="ts">import { onBeforeUnmount,onMounted,watch,ref } from 'vue';import * as echarts from 'echarts/core';import { LineChart } from 'echarts/charts';import { GridComponent,TooltipComponent } from 'echarts/components';import { CanvasRenderer } from 'echarts/renderers';echarts.use([LineChart,GridComponent,TooltipComponent,CanvasRenderer]);const props=defineProps<{points:{ts:number;value:number}[]}>();const el=ref<HTMLDivElement|null>(null);let chart:echarts.ECharts|null=null;let observer:ResizeObserver|undefined;let resizeTimer:number|undefined;const draw=()=>{if(!el.value)return;if(!chart)chart=echarts.init(el.value);chart.setOption({animationDuration:250,grid:{left:10,right:10,top:10,bottom:20,containLabel:true},tooltip:{trigger:'axis'},xAxis:{type:'category',boundaryGap:false,data:props.points.map(x=>new Date(x.ts).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})),axisLine:{lineStyle:{color:'var(--line)'}},axisLabel:{color:'var(--text-muted)'}},yAxis:{type:'value',scale:true,axisLabel:{color:'var(--text-muted)'},splitLine:{lineStyle:{color:'var(--line)'}}},series:[{type:'line',smooth:true,showSymbol:false,data:props.points.map(x=>x.value),lineStyle:{width:2,color:'var(--accent)'},areaStyle:{color:'rgba(37,99,235,.08)'}}]});chart.resize();};const scheduleDraw=()=>{if(resizeTimer)window.clearTimeout(resizeTimer);resizeTimer=window.setTimeout(()=>{resizeTimer=undefined;draw()},100)};onMounted(()=>{draw();observer=new ResizeObserver(scheduleDraw);if(el.value)observer.observe(el.value)});watch(()=>props.points,draw,{deep:true});onBeforeUnmount(()=>{observer?.disconnect();if(resizeTimer)window.clearTimeout(resizeTimer);chart?.dispose()});</script><template><div ref="el" class="equity-chart"></div></template>
